import { createContext, useContext, useEffect, useState, type FormEvent, type ReactNode } from 'react';
import { Link, Route, Switch, useLocation } from 'wouter';
import { Activity, ArrowRight, BadgeCheck, Bell, CalendarDays, Check, ChevronRight, ClipboardList, Clock3, HeartPulse, Home, LogOut, RotateCcw, Search, Stethoscope, Users, X, ClipboardPlus, Hospital, FileHeart, MapPin, CircleAlert, ArrowUpRight, Sparkles, UserRound } from 'lucide-react';

type Role = 'patient' | 'triage' | 'doctor' | 'admin';
type Patient = { id: string; name: string; phone: string; visitType: 'Walk-in'|'Appointment'; symptoms: string; state: 'waiting_for_triage'|'with_doctor'|'referred'|'pharmacy'|'complete'; doctor?: string; vitals?: {bp:string;temp:string;weight:string;priority:string}; created: string; };
type Referral = {id:string;patientId:string;patientName:string;doctor:string;department:string;reason:string;urgency:string;created:string};
type User = {role:Role;name:string;phone?:string;doctor?:string;};
type Store = {user:User|null;patients:Patient[];referrals:Referral[];login:(u:User)=>void;logout:()=>void;addPatient:(p:Partial<Patient>)=>Patient;assignDoctor:(id:string,doctor:string,vitals:NonNullable<Patient['vitals']>)=>void;sendReferral:(id:string,department:string,reason:string,urgency:string)=>void;checkin:(id:string)=>boolean;reset:()=>void;toast:(s:string)=>void;};
const doctors=[{name:'Dr. Musoke',specialty:'Cardiology'},{name:'Dr. Achieng',specialty:'Pediatrics'},{name:'Dr. Ouma',specialty:'General'}];
const initialPatients:Patient[]=[
 {id:'RRH-1048',name:'Grace',phone:'0700 000 148',visitType:'Walk-in',symptoms:'Chest pain and shortness of breath',state:'waiting_for_triage',created:'Today, 9:12 AM'},
 {id:'RRH-1047',name:'John',phone:'0700 000 147',visitType:'Appointment',symptoms:'Follow-up consultation',doctor:'Dr. Achieng',state:'waiting_for_triage',created:'Today, 8:45 AM'},
 {id:'RRH-1046',name:'Mary',phone:'0700 000 146',visitType:'Walk-in',symptoms:'Persistent headache',doctor:'Dr. Musoke',state:'with_doctor',vitals:{bp:'118/76',temp:'36.8',weight:'62',priority:'Routine'},created:'Today, 8:20 AM'}
];
const STORE_KEY='rrh-outpatient-prototype-v1';
const Ctx=createContext<Store|null>(null);
function createInitial(){return {user:null as User|null,patients:initialPatients,referrals:[] as Referral[]};}
function AppProvider({children}:{children:ReactNode}){
 const [data,setData]=useState(createInitial);
 const [notice,setNotice]=useState('');
 useEffect(()=>{try{const saved=localStorage.getItem(STORE_KEY);if(saved)setData(JSON.parse(saved));}catch{localStorage.removeItem(STORE_KEY)}},[]);
 useEffect(()=>{localStorage.setItem(STORE_KEY,JSON.stringify(data));},[data]);
 const toast=(s:string)=>{setNotice(s);window.setTimeout(()=>setNotice(''),3000)};
 const value:Store={
  ...data,
  login:(user)=>setData(d=>({...d,user})),
  logout:()=>setData(d=>({...d,user:null})),
  addPatient:(p)=>{const patient:Patient={id:`RRH-${Math.floor(1100+Math.random()*800)}`,name:p.name||'Patient',phone:p.phone||'',visitType:p.visitType||'Walk-in',symptoms:p.symptoms||'Consultation requested',state:'waiting_for_triage',doctor:p.doctor,created:'Today, just now'};setData(d=>({...d,patients:[patient,...d.patients]}));return patient;},
  assignDoctor:(id,doctor,vitals)=>setData(d=>({...d,patients:d.patients.map(p=>p.id===id?{...p,state:'with_doctor',doctor,vitals}:p)})),
  sendReferral:(id,department,reason,urgency)=>setData(d=>{const p=d.patients.find(x=>x.id===id);if(!p)return d;const referral:Referral={id:`REF-${Date.now().toString().slice(-5)}`,patientId:id,patientName:p.name,doctor:p.doctor||'Doctor',department,reason,urgency,created:'Today, just now'};return {...d,referrals:[referral,...d.referrals],patients:d.patients.map(x=>x.id===id?{...x,state:'referred'}:x)};}),
  checkin:(id)=>{const value=id.trim().toLowerCase();const found=data.patients.some(p=>p.id.toLowerCase()===value||p.phone.toLowerCase()===value);if(found)setData(d=>({...d,patients:d.patients.map(p=>p.id.toLowerCase()===value||p.phone.toLowerCase()===value?{...p,state:'waiting_for_triage'}:p)}));return found;},
  reset:()=>{setData(createInitial());localStorage.removeItem(STORE_KEY);toast('Prototype data restored');},
  toast,
 };
 return <Ctx.Provider value={value}>{children}<ReferralEventHost/>{notice&&<div className="toast fixed z-[80] bottom-6 left-1/2 -translate-x-1/2 flex items-center gap-2 rounded-xl bg-[#28302c] px-5 py-3 text-sm font-medium text-white shadow-xl" role="status" data-testid="toast-message"><Check size={16}/>{notice}</div>}</Ctx.Provider>;
}
function useApp(){const v=useContext(Ctx);if(!v)throw new Error('App context missing');return v;}
const navItems=[{href:'/staff/triage',label:'Triage queue',icon:ClipboardList,roles:['triage','admin']},{href:'/staff/doctor',label:'Doctor desk',icon:Stethoscope,roles:['doctor','admin']},{href:'/staff/admin',label:'Overview',icon:Activity,roles:['admin']},{href:'/staff/referrals',label:'Referrals',icon:ClipboardPlus,roles:['triage','admin']}];
function ResetControl(){const {reset}=useApp();return <button onClick={reset} data-testid="button-reset-prototype" className="reset-control fixed z-40 bottom-4 right-4 flex items-center gap-2 rounded-full border border-white/70 bg-[#f7f8f7] px-4 py-2.5 text-xs font-semibold text-[#56625b] shadow-lg hover:bg-white focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[#819c88]"><RotateCcw size={14}/> Reset Prototype</button>}
function Logo({small=false}:{small?:boolean}){return <Link href="/" data-testid="link-home-logo" className="flex items-center gap-2.5 text-[#242a27] no-underline"><span className="grid h-8 w-8 place-items-center rounded-[11px] bg-[#272e2a] text-white"><Hospital size={17}/></span><span className={`font-[family-name:var(--font-serif)] font-bold tracking-[-.04em] ${small?'text-[18px]':'text-[20px]'}`}>RRH<span className="font-medium text-[#68746d]">.care</span></span></Link>}
function UserBadge({name,role}:{name:string;role:string}){return <div className="flex items-center gap-2.5"><div className="grid h-9 w-9 place-items-center rounded-full bg-[#d7e2d8] text-sm font-bold text-[#43564a]">{name.slice(0,1).toUpperCase()}</div><div className="hidden sm:block"><div className="text-xs font-semibold text-[#313936]">{name}</div><div className="text-[10px] capitalize text-[#7c8580]">{role}</div></div></div>}
function StaffLayout({children,title}:{children:ReactNode;title:string}){
 const {user,logout,toast}=useApp();const [path,setPath]=useLocation();
 const role=user?.role||'triage';
 return <div className="app-shell staff-layout">
  <aside className="staff-sidebar flex flex-col border-r border-white/70 px-4 py-5">
   <div className="mb-9 px-2"><Logo/></div>
   <p className="mb-3 px-3 text-[10px] font-bold uppercase tracking-[.16em] text-[#929a95]">Workspace</p>
   <nav className="space-y-1">{navItems.filter(n=>n.roles.includes(role)).map(({href,label,icon:Icon})=><Link key={href} href={href} data-testid={`nav-${label.toLowerCase().replaceAll(' ','-')}`} className={`side-link ${path===href?'active':''}`}><Icon size={16}/>{label}{path===href&&<ArrowRight className="ml-auto" size={14}/>}</Link>)}</nav>
   <div className="mt-auto rounded-2xl bg-[#dce4dd] p-4"><div className="mb-2 flex items-center gap-2 text-xs font-semibold"><HeartPulse size={15}/>Outpatient care</div><p className="text-[11px] leading-relaxed text-[#68736c]">A calm, coordinated visit from reception to recovery.</p></div>
  </aside>
  <div className="staff-main min-w-0">
   <header className="sticky top-0 z-20 flex h-[66px] items-center justify-between border-b border-white/80 bg-[#e9ebea]/95 px-5 backdrop-blur md:px-8">
    <div className="flex items-center gap-2"><span className="text-xs text-[#84908a]">Outpatient</span><ChevronRight size={13} className="text-[#a5aca8]"/><h1 className="text-sm font-semibold">{title}</h1></div>
    <div className="flex items-center gap-3"><span className="hidden rounded-full border border-white/80 bg-[#f4f5f4] px-3 py-1.5 text-[11px] text-[#727c76] sm:inline-flex">Regional Referral Hospital</span><button title="Notifications" onClick={()=>toast('You’re all caught up')} className="grid h-9 w-9 place-items-center rounded-full bg-[#f3f4f3] text-[#59635d]" data-testid="button-notifications"><Bell size={16}/></button><UserBadge name={user?.name||'Staff'} role={role}/><button onClick={()=>{logout();setPath('/')}} aria-label="Log out" className="grid h-9 w-9 place-items-center rounded-full bg-[#f3f4f3] text-[#59635d] hover:bg-[#dfe4e0]" data-testid="button-logout"><LogOut size={16}/></button></div>
   </header>
   <main className="mx-auto max-w-[1280px] px-4 py-6 md:px-8 md:py-8">{children}</main>
  </div>
 </div>;
}
function PatientLayout({children,title}:{children:ReactNode;title:string}){
 const {user,logout}=useApp();const [path,setPath]=useLocation();
  const patientNav=[{href:'/patient/home',label:'Home',icon:Home},{href:'/patient/book',label:'Book',icon:CalendarDays},{href:'/patient/records',label:'Records',icon:FileHeart},{href:'/patient/profile',label:'Profile',icon:UserRound}];
 return <div className="app-shell mx-auto max-w-[1000px]">
  <header className="flex h-[66px] items-center justify-between border-b border-white/80 px-5 md:px-8"><Logo/><div className="flex items-center gap-3"><span className="hidden text-[11px] text-[#7e8982] sm:block">Regional Referral Hospital</span>{user&&<><UserBadge name={user.name} role="patient"/><button onClick={()=>{logout();setPath('/')}} className="grid h-9 w-9 place-items-center rounded-full bg-white/65 text-[#59635d]" aria-label="Log out" data-testid="button-logout"><LogOut size={15}/></button></>}</div></header>
  <main className="patient-content mx-auto max-w-[760px] px-4 py-7 md:px-8 md:py-10">{title==='Home'&&<div className="mb-4 flex justify-end"><Link href="/patient/tracker" className="inline-flex items-center gap-1.5 rounded-full border border-white bg-[#f7f8f7] px-3.5 py-2 text-[11px] font-semibold text-[#58665d] no-underline hover:bg-white" data-testid="link-home-tracker">Visit tracker <ArrowRight size={13}/></Link></div>}{children}</main>
  <nav className="patient-bottom mx-auto hidden max-w-[620px] rounded-2xl border border-white bg-[#f7f8f7]/95 p-2 shadow-xl md:!flex md:fixed md:bottom-4 md:left-1/2 md:-translate-x-1/2">{patientNav.map(({href,label,icon:Icon})=><Link href={href} key={href} data-testid={`patient-nav-${label.toLowerCase().replace(' ','-')}`} className={`flex flex-1 flex-col items-center gap-1 rounded-xl py-2 text-[10px] font-semibold no-underline ${path===href?'bg-[#282e2b] text-white':'text-[#737d76] hover:bg-[#e8ece9]'}`}><Icon size={17}/>{label}</Link>)}</nav>
  <nav className="patient-bottom fixed bottom-3 left-3 right-3 z-30 grid grid-cols-4 rounded-2xl border border-white bg-[#f7f8f7]/95 p-2 shadow-xl md:hidden">{patientNav.map(({href,label,icon:Icon})=><Link href={href} key={href} data-testid={`patient-nav-${label.toLowerCase().replace(' ','-')}`} className={`flex flex-col items-center gap-1 rounded-xl py-2 text-[10px] font-semibold no-underline ${path===href?'bg-[#282e2b] text-white':'text-[#737d76]'}`}><Icon size={17}/>{label}</Link>)}</nav>
 </div>;
}
function PageIntro({eyebrow,title,sub}:{eyebrow?:string;title:string;sub?:string}){return <div className="mb-6"><div className="mb-2 text-[10px] font-bold uppercase tracking-[.16em] text-[#839087]">{eyebrow||'Outpatient services'}</div><h2 className="font-[family-name:var(--font-serif)] text-[26px] font-bold tracking-[-.04em] text-[#252c28] md:text-[30px]">{title}</h2>{sub&&<p className="mt-1.5 max-w-xl text-sm leading-relaxed text-[#737d76]">{sub}</p>}</div>}
function StatusPill({state}:{state:Patient['state']}){const label:Record<Patient['state'],string>={waiting_for_triage:'Waiting for triage',with_doctor:'With doctor',referred:'Referred',pharmacy:'Pharmacy',complete:'Complete'};return <span data-testid={`status-${state}`} className={`inline-flex items-center rounded-full px-2.5 py-1 text-[10px] font-semibold ${state==='waiting_for_triage'?'bg-[#f5e9d4] text-[#8a6837]':state==='with_doctor'?'bg-[#dce8df] text-[#476550]':state==='referred'?'bg-[#e2e5ef] text-[#5b6383]':'bg-[#e7ebe7] text-[#66716a]'}`}>{label[state]}</span>}
function Landing(){return <div className="app-shell min-h-[calc(100dvh-32px)]">
 <header className="flex h-[68px] items-center justify-between px-5 md:px-10"><Logo/><span className="flex items-center gap-2 rounded-full bg-[#f3f5f3] px-3 py-2 text-[11px] text-[#68736c]"><MapPin size={13}/>Regional Referral Hospital</span></header>
 <main className="mx-auto max-w-[1250px] px-5 pb-10 pt-8 md:px-10 md:pt-12">
  <div className="grid gap-5 lg:grid-cols-[1.4fr_.85fr]">
   <section className="sage-panel relative flex min-h-[360px] flex-col justify-between overflow-hidden p-7 md:p-10">
    <div className="absolute -right-16 -top-20 h-64 w-64 rounded-full border border-white/30"/><div className="absolute right-10 top-12 h-36 w-36 rounded-full border border-white/30"/>
    <div className="relative"><span className="mb-5 inline-flex items-center gap-2 rounded-full border border-white/70 bg-white/40 px-3 py-1.5 text-[10px] font-semibold uppercase tracking-[.12em] text-[#4c6252]"><Sparkles size={13}/> Care, made clearer</span><h1 className="max-w-[610px] font-[family-name:var(--font-serif)] text-[40px] font-bold leading-[1.08] tracking-[-.055em] text-[#26302a] md:text-[56px]">Your visit, with a little more peace of mind.</h1><p className="mt-4 max-w-md text-sm leading-relaxed text-[#54635a]">Book an outpatient appointment, check in, and follow each step of your care — all in one place.</p></div>
    <div className="relative mt-8 flex flex-wrap items-center gap-3"><Link href="/auth/patient" className="btn-primary inline-flex items-center gap-3 px-5 py-3.5 text-sm no-underline" data-testid="link-patient-entry">I am a patient <ArrowRight size={16}/></Link><div className="flex items-center gap-2 text-[11px] text-[#536157]"><BadgeCheck size={15}/>Private and simple to use</div></div>
   </section>
   <section className="panel flex flex-col justify-between p-6 md:p-8"><div><div className="mb-5 flex h-12 w-12 items-center justify-center rounded-2xl bg-[#e2e9e3] text-[#506858]"><Stethoscope size={22}/></div><div className="mb-2 text-[10px] font-bold uppercase tracking-[.15em] text-[#89938d]">For hospital teams</div><h2 className="font-[family-name:var(--font-serif)] text-[27px] font-bold tracking-[-.04em]">A smoother shift starts here.</h2><p className="mt-2 max-w-sm text-sm leading-relaxed text-[#737d76]">Coordinate triage, consultations and referrals with one shared view of the patient journey.</p></div><div className="mt-8"><Link href="/auth/staff" className="btn-soft inline-flex items-center gap-3 px-5 py-3.5 text-sm font-semibold no-underline" data-testid="link-staff-entry">Hospital staff sign in <ArrowRight size={16}/></Link><p className="mt-3 text-[11px] text-[#909994]">Local demonstration · No real patient data</p></div></section>
  </div>
  <div className="mt-5 grid gap-4 md:grid-cols-3">
   {[{icon:CalendarDays,title:'Plan a visit',desc:'Choose a service or tell us what you need.'},{icon:Activity,title:'Know what’s next',desc:'Follow your progress through each care step.'},{icon:HeartPulse,title:'One connected team',desc:'From reception to pharmacy, your care stays coordinated.'}].map(({icon:Icon,title,desc})=><div key={title} className="panel flex items-start gap-4 p-5"><div className="grid h-10 w-10 shrink-0 place-items-center rounded-xl bg-[#e8ece9] text-[#607469]"><Icon size={18}/></div><div><h3 className="text-sm font-semibold">{title}</h3><p className="mt-1 text-xs leading-relaxed text-[#7a847e]">{desc}</p></div></div>)}
  </div>
 </main></div>}
 function PatientAuth(){const {login,toast}=useApp();const [,setPath]=useLocation();const [name,setName]=useState('');const [phone,setPhone]=useState('');const [err,setErr]=useState('');function submit(e:FormEvent){e.preventDefault();if(name.trim().length<2){setErr('Enter your full name to continue.');return;}if(phone.replace(/\D/g,'').length<9){setErr('Enter a valid phone number.');return;}login({role:'patient',name:name.trim(),phone:phone.trim()});toast('Welcome to your care space');setPath('/patient/home');}
 return <PatientLayout title="Patient sign in"><PageIntro eyebrow="Patient access" title="Welcome in" sub="Enter your details to see your visits, make a booking or check in."/><form onSubmit={submit} className="panel space-y-5 p-5 md:p-7" noValidate><label className="block text-xs font-semibold">Full name<input className="field mt-2" placeholder="e.g. Amina Nambasa" value={name} onChange={e=>{setName(e.target.value);setErr('')}} data-testid="input-patient-name" autoComplete="name"/></label><label className="block text-xs font-semibold">Phone number<input className="field mt-2" placeholder="+256 7XX XXX XXX" value={phone} onChange={e=>{setPhone(e.target.value);setErr('')}} data-testid="input-patient-phone" autoComplete="tel" inputMode="tel"/></label>{err&&<p className="text-xs text-[#a84942]" role="alert">{err}</p>}<button type="submit" className="btn-primary flex w-full items-center justify-center gap-2 py-3.5 text-sm" data-testid="button-patient-continue">Continue <ArrowRight size={15}/></button><Link href="/" className="block text-center text-xs text-[#77827b] no-underline hover:text-[#303a34]">Back to welcome</Link></form></PatientLayout>}
function StaffAuth(){const {login,toast}=useApp();const [,setPath]=useLocation();const [role,setRole]=useState<Role>('triage');const [staffId,setStaffId]=useState('');const [password,setPassword]=useState('');const [doctor,setDoctor]=useState(doctors[0].name);const [err,setErr]=useState('');function submit(e:FormEvent){e.preventDefault();if(!staffId.trim()||password.length<3){setErr('Enter your staff ID and a password of at least 3 characters.');return;}const name=role==='doctor'?doctor:staffId.trim();login({role,name,doctor:role==='doctor'?doctor:undefined});toast(`Signed in as ${role}`);setPath(role==='triage'?'/staff/triage':role==='doctor'?'/staff/doctor':'/staff/admin');}
 return <div className="app-shell min-h-[calc(100dvh-32px)]"><header className="flex h-[66px] items-center px-5 md:px-9"><Logo/></header><main className="mx-auto grid max-w-[1040px] gap-8 px-5 py-7 md:grid-cols-[.8fr_1fr] md:items-center md:px-10 md:py-12"><div><div className="sage-panel mb-6 grid min-h-[210px] place-items-center p-8 md:min-h-[280px]"><div className="text-center"><div className="mx-auto mb-4 grid h-16 w-16 place-items-center rounded-[22px] bg-white/55 text-[#526a58]"><Hospital size={30}/></div><p className="text-xs font-semibold uppercase tracking-[.16em] text-[#617263]">Regional Referral Hospital</p><p className="mt-2 font-[family-name:var(--font-serif)] text-2xl font-bold tracking-tight">Outpatient care, in sync.</p></div></div><p className="text-sm leading-relaxed text-[#77817b]">A shared workspace for the people moving care forward, one patient at a time.</p></div><section><PageIntro eyebrow="Team access" title="Staff sign in" sub="Choose your role to open the right workspace."/><form onSubmit={submit} className="panel space-y-4 p-5 md:p-7" noValidate><div><div className="mb-2 text-xs font-semibold">Your workspace</div><div className="grid grid-cols-3 gap-2">{(['triage','doctor','admin'] as Role[]).map(r=><button key={r} type="button" onClick={()=>setRole(r)} data-testid={`role-${r}`} className={`rounded-xl border px-2 py-2.5 text-xs font-semibold capitalize ${role===r?'border-[#344038] bg-[#29312c] text-white':'border-white bg-[#f0f2f0] text-[#68736c] hover:bg-[#e5e9e6]'}`}>{r}</button>)}</div></div><label className="block text-xs font-semibold">Staff ID<input className="field mt-2" value={staffId} onChange={e=>setStaffId(e.target.value)} placeholder="Enter your staff ID" data-testid="input-staff-id"/></label><label className="block text-xs font-semibold">Password<input type="password" className="field mt-2" value={password} onChange={e=>setPassword(e.target.value)} placeholder="Enter password" data-testid="input-staff-password"/></label>{role==='doctor'&&<label className="block text-xs font-semibold">Doctor profile<select className="field mt-2" value={doctor} onChange={e=>setDoctor(e.target.value)} data-testid="select-doctor">{doctors.map(d=><option key={d.name} value={d.name}>{d.name} · {d.specialty}</option>)}</select></label>}{err&&<p className="text-xs text-[#a84942]" role="alert">{err}</p>}<button className="btn-primary w-full py-3.5 text-sm" type="submit" data-testid="button-staff-signin">Enter workspace <ArrowRight size={15} className="ml-2 inline"/></button><p className="text-center text-[10px] text-[#89938d]">Demo sign in · Any ID and password accepted</p><Link href="/" className="block text-center text-xs text-[#77827b] no-underline hover:text-[#303a34]">Back to welcome</Link></form></section></main></div>}
function PatientHome(){const {user,patients}=useApp();const mine=patients.find(p=>p.name.toLowerCase()===user?.name.toLowerCase());const [path,setPath]=useLocation();const statusCopy=mine?({waiting_for_triage:'You’re checked in and waiting for triage.',with_doctor:'Your care team is ready to see you.',referred:'A referral has been sent for your care.',pharmacy:'Your visit is at the pharmacy step.',complete:'Your visit is complete.'}[mine.state]):'No active visits at the moment.';return <PatientLayout title="Home"><div className="mb-6 flex items-center justify-between"><div><div className="text-xs text-[#87918b]">Good day,</div><h2 className="font-[family-name:var(--font-serif)] text-[28px] font-bold tracking-[-.04em]">{user?.name}</h2></div><div className="grid h-11 w-11 place-items-center rounded-full bg-[#d9e3da] text-[#52685a]"><HeartPulse size={20}/></div></div><section className="sage-panel relative overflow-hidden p-6 md:p-7" data-testid="patient-status-card"><div className="flex items-start justify-between"><div><div className="mb-2 text-[10px] font-bold uppercase tracking-[.15em] text-[#5e7162]">Your visit status</div><h3 className="max-w-sm font-[family-name:var(--font-serif)] text-xl font-bold">{mine?'Visit in progress':'Your care starts here'}</h3><p className="mt-2 max-w-sm text-sm leading-relaxed text-[#536257]">{statusCopy}</p></div><div className="rounded-full bg-white/50 p-3 text-[#506454]"><Activity size={21}/></div></div>{mine&&<div className="mt-5 flex flex-wrap items-center justify-between gap-3 border-t border-white/45 pt-4"><div className="text-xs text-[#526157]"><span className="font-semibold">{mine.id}</span> <span className="mx-1">·</span>{mine.visitType}</div><button onClick={()=>setPath('/patient/tracker')} className="inline-flex items-center gap-1 text-xs font-semibold text-[#334439]" data-testid="button-track-visit">Track visit <ArrowRight size={14}/></button></div>}</section><div className="mt-6 grid gap-3 sm:grid-cols-2"><button onClick={()=>setPath('/patient/book')} className="panel flex items-center gap-4 p-5 text-left transition hover:-translate-y-0.5" data-testid="button-book-visit"><span className="grid h-11 w-11 place-items-center rounded-xl bg-[#e5ebe6] text-[#5b7060]"><CalendarDays size={20}/></span><span className="flex-1"><b className="block text-sm">Book a visit</b><small className="mt-1 block text-xs text-[#818b85]">Choose a doctor or describe your needs</small></span><ArrowRight size={16}/></button><button onClick={()=>setPath('/patient/checkin')} className="panel flex items-center gap-4 p-5 text-left transition hover:-translate-y-0.5" data-testid="button-check-in"><span className="grid h-11 w-11 place-items-center rounded-xl bg-[#e5ebe6] text-[#5b7060]"><ClipboardList size={20}/></span><span className="flex-1"><b className="block text-sm">Check in</b><small className="mt-1 block text-xs text-[#818b85]">Already here? Join the triage queue</small></span><ArrowRight size={16}/></button></div><section className="panel mt-5 p-5"><div className="flex items-center justify-between"><h3 className="text-sm font-semibold">A little guidance</h3><span className="text-[10px] text-[#929a95]">For your visit</span></div><div className="mt-4 flex gap-3"><div className="grid h-8 w-8 shrink-0 place-items-center rounded-full bg-[#edf0ed] text-[#67766c]"><CircleAlert size={16}/></div><p className="text-xs leading-relaxed text-[#768079]">If you feel suddenly unwell while waiting, please tell a member of the hospital team right away.</p></div></section></PatientLayout>}
function PatientBook(){const {user,addPatient,toast}=useApp();const [,setPath]=useLocation();const [mode,setMode]=useState<'doctor'|'symptoms'>('doctor');const [specialty,setSpecialty]=useState('Cardiology');const [doctor,setDoctor]=useState('Dr. Musoke');const [time,setTime]=useState('Today · 10:30 AM');const [symptoms,setSymptoms]=useState('');const [err,setErr]=useState('');const avail=doctors.filter(d=>d.specialty===specialty);function submit(e:FormEvent){e.preventDefault();if(mode==='symptoms'&&symptoms.trim().length<8){setErr('Please describe your symptoms in a little more detail.');return;}const doc=mode==='doctor'?doctor:undefined;addPatient({name:user?.name,phone:user?.phone||'',visitType:'Appointment',doctor:doc,symptoms:mode==='doctor'?`${specialty} appointment · ${time}`:symptoms.trim()});toast('Booking sent · You’re in the triage queue');setPath('/patient/home');}return <PatientLayout title="Book a visit"><PageIntro eyebrow="Plan your care" title="Book a visit" sub="Tell us what kind of support you need. The care team will take it from here."/><div className="mb-4 grid grid-cols-2 rounded-2xl bg-[#dfe4e0] p-1.5"><button onClick={()=>{setMode('doctor');setErr('')}} className={`rounded-xl py-3 text-xs font-semibold ${mode==='doctor'?'bg-[#fafbfa] text-[#303a34] shadow-sm':'text-[#737e77]'}`} data-testid="tab-known-doctor">I know who I need</button><button onClick={()=>{setMode('symptoms');setErr('')}} className={`rounded-xl py-3 text-xs font-semibold ${mode==='symptoms'?'bg-[#fafbfa] text-[#303a34] shadow-sm':'text-[#737e77]'}`} data-testid="tab-need-guidance">I’m not sure</button></div><form onSubmit={submit} className="panel space-y-5 p-5 md:p-7">{mode==='doctor'?<><div><label className="mb-2 block text-xs font-semibold">Choose a specialty</label><select className="field" value={specialty} onChange={e=>{setSpecialty(e.target.value);const next=doctors.find(d=>d.specialty===e.target.value);if(next)setDoctor(next.name)}} data-testid="select-specialty">{doctors.map(d=><option key={d.specialty}>{d.specialty}</option>)}</select></div><div><label className="mb-2 block text-xs font-semibold">Preferred doctor</label><select className="field" value={doctor} onChange={e=>setDoctor(e.target.value)} data-testid="select-booking-doctor">{avail.map(d=><option key={d.name} value={d.name}>{d.name}</option>)}</select></div><div><label className="mb-2 block text-xs font-semibold">Preferred time</label><select className="field" value={time} onChange={e=>setTime(e.target.value)} data-testid="select-booking-time"><option>Today · 10:30 AM</option><option>Today · 1:00 PM</option><option>Tomorrow · 9:00 AM</option></select></div></>:<div><label className="mb-2 block text-xs font-semibold">What would you like help with?</label><textarea className="field min-h-32 resize-y" value={symptoms} onChange={e=>{setSymptoms(e.target.value);setErr('')}} placeholder="Share your symptoms or what has been concerning you…" data-testid="input-booking-symptoms"/><p className="mt-2 text-[11px] text-[#89938d]">A nurse will help guide you to the right service.</p></div>}{err&&<p className="text-xs text-[#a84942]" role="alert">{err}</p>}<button className="btn-primary w-full py-3.5 text-sm" data-testid="button-submit-booking">Send booking request <ArrowRight size={15} className="ml-2 inline"/></button></form></PatientLayout>}
function CheckIn(){const {patients,checkin,toast}=useApp();const [path,setPath]=useLocation();const [id,setId]=useState('');const [err,setErr]=useState('');function submit(e:FormEvent){e.preventDefault();const match=patients.find(p=>p.id.toLowerCase()===id.trim().toLowerCase()||p.phone===id.trim()||(p.name.toLowerCase()===id.trim().toLowerCase()&&p.name.toLowerCase()===useAppName));if(!id.trim()){setErr('Enter your patient ID or phone number.');return;}const found=checkin(id);if(found){toast('You’re checked in');setPath('/patient/tracker')}else setErr('We couldn’t find that visit. Check your patient ID or phone number.');}
 const useAppName='';
 return <PatientLayout title="Check in"><PageIntro eyebrow="At the hospital" title="Check in for your visit" sub="Enter the patient ID from your booking confirmation to join the queue."/><form onSubmit={submit} className="panel space-y-5 p-5 md:p-7"><label className="block text-xs font-semibold">Patient ID or phone number<input className="field mt-2" value={id} onChange={e=>{setId(e.target.value);setErr('')}} placeholder="e.g. RRH-1048" data-testid="input-checkin-id"/></label>{err&&<p role="alert" className="text-xs text-[#a84942]">{err}</p>}<button className="btn-primary flex w-full items-center justify-center gap-2 py-3.5 text-sm" type="submit" data-testid="button-submit-checkin">Check in <ArrowRight size={15}/></button><div className="rounded-xl bg-[#eef1ee] p-4 text-xs leading-relaxed text-[#717c74]"><b className="text-[#48534c]">Can’t find your ID?</b><br/>Ask the reception desk for help checking in.</div></form></PatientLayout>}
function Tracker(){const {user,patients}=useApp();const p=patients.find(x=>x.name.toLowerCase()===user?.name.toLowerCase());const steps=['Reception','Triage','Doctor','Pharmacy'];const active=p?.state==='waiting_for_triage'?1:p?.state==='with_doctor'?2:p?.state==='referred'?2:p?.state==='pharmacy'?3:p?.state==='complete'?4:0;return <PatientLayout title="Visit tracker"><PageIntro eyebrow="Your care journey" title="Visit tracker" sub="See where you are and what comes next."/><section className="sage-panel mb-5 p-5 md:p-6"><div className="flex items-start justify-between gap-4"><div><div className="text-[10px] font-bold uppercase tracking-[.14em] text-[#607163]">Current visit</div><h3 className="mt-1 text-lg font-bold">{p?`Hello, ${p.name}`:'No active visit yet'}</h3><p className="mt-1 text-xs text-[#617066]">{p?`${p.id} · ${p.visitType}`:'Book a visit or check in to see your progress.'}</p></div>{p&&<StatusPill state={p.state}/>}</div></section><section className="panel p-5 md:p-7"><h3 className="mb-6 text-sm font-semibold">Your visit steps</h3>{steps.map((step,i)=><div className="relative flex gap-4 pb-7 last:pb-0" key={step}><div className="flex flex-col items-center"><div className={`z-10 grid h-8 w-8 place-items-center rounded-full ${i<active?'bg-[#63806a] text-white':i===active?'bg-[#29312c] text-white':'bg-[#edf0ed] text-[#9aa29d]'}`}>{i<active?<Check size={15}/>:<span className="text-xs font-semibold">{i+1}</span>}</div>{i<steps.length-1&&<div className={`absolute left-[15px] top-8 h-[calc(100%-30px)] w-px ${i<active?'bg-[#8aa28f]':'bg-[#e1e5e2]'}`}/>}</div><div className="pt-1"><div className={`text-sm font-semibold ${i===active?'text-[#2c352f]':'text-[#747e78]'}`}>{step}</div><p className="mt-1 text-xs text-[#89928d]">{i===active?(p?i===1?'The triage team will check your vital signs.':i===2?'Your care team is ready to see you.':'Your visit is underway.':'Start by checking in at reception.') :i<active?'Complete':'Up next'}</p></div></div>)}</section><p className="mt-4 flex items-center gap-2 text-[11px] text-[#838d86]"><Clock3 size={13}/>Your care team will update your status as your visit progresses.</p></PatientLayout>}

function belongsToPatient(record:Patient,user:User|null){return Boolean(user?.role==='patient'&&((user.phone&&record.phone===user.phone)||record.name.trim().toLowerCase()===user.name.trim().toLowerCase()));}
function PatientRecords(){const {user,patients}=useApp();const records=patients.filter(p=>belongsToPatient(p,user));const [path,setPath]=useLocation();return <PatientLayout title="Records"><PageIntro eyebrow="Your care" title="Visit records" sub="A simple history of your outpatient visits and where each one stands."/><div className="mb-4 flex items-center justify-between"><span className="text-xs text-[#818b85]">{records.length} {records.length===1?'visit':'visits'} on record</span><button onClick={()=>setPath('/patient/tracker')} className="inline-flex items-center gap-1.5 text-xs font-semibold text-[#53675a]" data-testid="button-records-tracker">Open visit tracker <ArrowRight size={14}/></button></div>{records.length?<div className="space-y-3">{records.map(p=><article key={p.id} className="panel p-5" data-testid={`card-patient-record-${p.id}`}><div className="flex flex-wrap items-start justify-between gap-3"><div><div className="flex items-center gap-2"><h3 className="text-sm font-semibold">{p.visitType} visit</h3><StatusPill state={p.state}/></div><div className="mt-1.5 text-[11px] text-[#87918b]">{p.id} <span className="mx-1.5">·</span>{p.created}</div></div><div className="text-right text-[11px] text-[#78837c]">{p.doctor||'Care team'}<div className="mt-1 text-[10px] text-[#969e99]">{p.vitals?.priority||'Outpatient care'}</div></div></div><p className="mt-4 border-t border-[#edf0ed] pt-3 text-xs leading-relaxed text-[#727d76]">{p.symptoms}</p>{p.vitals&&<div className="mt-3 flex flex-wrap gap-x-4 gap-y-1 text-[10px] text-[#7c8780]"><span>Blood pressure <b className="text-[#46534b]">{p.vitals.bp}</b></span><span>Temperature <b className="text-[#46534b]">{p.vitals.temp} °C</b></span><span>Weight <b className="text-[#46534b]">{p.vitals.weight} kg</b></span></div>}</article>)}</div>:<section className="panel px-6 py-12 text-center" data-testid="empty-patient-records"><div className="mx-auto mb-3 grid h-12 w-12 place-items-center rounded-2xl bg-[#e8ede9] text-[#65776a]"><FileHeart size={20}/></div><h3 className="text-sm font-semibold">No visits on record yet</h3><p className="mx-auto mt-1 max-w-sm text-xs leading-relaxed text-[#818b85]">When you book a visit or check in at reception, your care history will appear here.</p><div className="mt-5 flex justify-center gap-2"><button onClick={()=>setPath('/patient/book')} className="btn-primary px-4 py-2.5 text-xs" data-testid="button-records-book">Book a visit</button><button onClick={()=>setPath('/patient/checkin')} className="btn-soft px-4 py-2.5 text-xs" data-testid="button-records-checkin">Check in</button></div></section>}</PatientLayout>}
function PatientProfile(){const {user,logout}=useApp();const [,setPath]=useLocation();return <PatientLayout title="Profile"><PageIntro eyebrow="Your details" title="Patient profile" sub="Your sign-in details stay on this device for this prototype."/><section className="sage-panel flex items-center gap-4 p-5 md:p-6"><div className="grid h-14 w-14 place-items-center rounded-full bg-white/55 text-lg font-bold text-[#4f6555]">{user?.name.slice(0,1).toUpperCase()}</div><div><div className="text-[10px] font-bold uppercase tracking-[.14em] text-[#65766a]">Patient account</div><h3 className="mt-1 text-lg font-bold">{user?.name}</h3></div></section><section className="panel mt-4 divide-y divide-[#e9ece9] px-5"><div className="py-4"><div className="text-[10px] font-bold uppercase tracking-wider text-[#89938d]">Full name</div><div className="mt-1 text-sm font-semibold" data-testid="text-profile-name">{user?.name}</div></div><div className="py-4"><div className="text-[10px] font-bold uppercase tracking-wider text-[#89938d]">Phone number</div><div className="mt-1 text-sm font-semibold" data-testid="text-profile-phone">{user?.phone||'Not provided'}</div></div><div className="py-4"><div className="text-[10px] font-bold uppercase tracking-wider text-[#89938d]">Data storage</div><div className="mt-1 text-xs text-[#727d76]">Saved locally in this browser only</div></div></section><button onClick={()=>{logout();setPath('/')}} className="btn-soft mt-5 flex w-full items-center justify-center gap-2 py-3.5 text-sm font-semibold" data-testid="button-patient-logout"><LogOut size={16}/> Log out</button></PatientLayout>}

function TriagePage(){const {patients,toast}=useApp();const [tab,setTab]=useState<'All'|'Walk-ins'|'Appointments'>('All');const [selected,setSelected]=useState<Patient|null>(null);const queue=patients.filter(p=>p.state==='waiting_for_triage'&&(tab==='All'||p.visitType===tab.slice(0,-1)||(tab==='Appointments'&&p.visitType==='Appointment')));
 return <StaffLayout title="Triage queue"><PageIntro eyebrow="Care coordination" title="Triage queue" sub="Review arrivals, record vital signs and guide each patient to the right clinician."/><div className="mb-5 grid gap-3 sm:grid-cols-3"><MiniStat label="Waiting for triage" value={patients.filter(p=>p.state==='waiting_for_triage').length} icon={Clock3}/><MiniStat label="Walk-ins" value={patients.filter(p=>p.state==='waiting_for_triage'&&p.visitType==='Walk-in').length} icon={Users}/><MiniStat label="Appointments" value={patients.filter(p=>p.state==='waiting_for_triage'&&p.visitType==='Appointment').length} icon={CalendarDays}/></div><div className="panel overflow-hidden"><div className="flex flex-wrap items-center justify-between gap-3 border-b border-[#e8ebe8] px-5 py-4"><div><h3 className="text-sm font-semibold">Patients to assess</h3><p className="mt-1 text-[11px] text-[#89938d]">{queue.length} patients in the queue</p></div><div className="flex gap-1 rounded-xl bg-[#edf0ed] p-1">{(['All','Walk-ins','Appointments'] as const).map(t=><button key={t} onClick={()=>setTab(t)} className={`rounded-lg px-3 py-2 text-[11px] font-semibold ${tab===t?'bg-white text-[#303a34] shadow-sm':'text-[#78827c]'}`} data-testid={`tab-triage-${t.toLowerCase().replace('-','')}`}>{t}</button>)}</div></div>{queue.length? <div className="divide-y divide-[#eceeec]">{queue.map(p=><div key={p.id} className="flex flex-wrap items-center gap-4 px-5 py-4" data-testid={`row-triage-${p.id}`}><div className="grid h-10 w-10 shrink-0 place-items-center rounded-full bg-[#e5ebe6] text-sm font-bold text-[#526458]">{p.name.slice(0,1)}</div><div className="min-w-[130px] flex-1"><div className="text-sm font-semibold">{p.name} <span className="ml-1 text-[10px] font-normal text-[#919a95]">{p.id}</span></div><div className="mt-1 max-w-lg truncate text-xs text-[#818b85]">{p.symptoms}</div></div><div className="hidden min-w-[92px] sm:block"><span className={`rounded-full px-2.5 py-1 text-[10px] font-semibold ${p.visitType==='Walk-in'?'bg-[#e9ece9] text-[#65716a]':'bg-[#edf0e3] text-[#737349]'}`}>{p.visitType}</span><div className="mt-2 text-[10px] text-[#959d98]">{p.created}</div></div>{p.doctor&&<div className="text-xs text-[#758078]">{p.doctor}</div>}<button onClick={()=>setSelected(p)} className="btn-primary flex items-center gap-2 px-4 py-2.5 text-xs" data-testid={`button-assess-${p.id}`}>Assess <ArrowRight size={14}/></button></div>)}</div>:<EmptyState title="Queue is clear" copy="There are no patients waiting for triage in this view." icon={Check}/>}</div>{selected&&<TriageModal patient={selected} onClose={()=>setSelected(null)} onSaved={()=>{toast('Patient sent to doctor');setSelected(null)}}/>}</StaffLayout>}
function MiniStat({label,value,icon:Icon}:{label:string;value:number|string;icon:typeof Activity}){return <div className="panel flex items-center gap-3 p-4"><div className="grid h-10 w-10 place-items-center rounded-xl bg-[#e8ede9] text-[#617367]"><Icon size={18}/></div><div><div className="font-[family-name:var(--font-serif)] text-2xl font-bold leading-none">{value}</div><div className="mt-1 text-[10px] text-[#87918b]">{label}</div></div></div>}
function EmptyState({title,copy,icon:Icon=ClipboardList}:{title:string;copy:string;icon?:typeof Activity}){return <div className="px-6 py-14 text-center" data-testid="empty-state"><div className="mx-auto mb-3 grid h-12 w-12 place-items-center rounded-2xl bg-[#edf0ed] text-[#78867c]"><Icon size={20}/></div><h3 className="text-sm font-semibold">{title}</h3><p className="mx-auto mt-1 max-w-xs text-xs leading-relaxed text-[#87918b]">{copy}</p></div>}
function TriageModal({patient,onClose,onSaved}:{patient:Patient;onClose:()=>void;onSaved:()=>void}){const {assignDoctor}=useApp();const [bp,setBp]=useState(patient.vitals?.bp||'');const [temp,setTemp]=useState(patient.vitals?.temp||'');const [weight,setWeight]=useState(patient.vitals?.weight||'');const [priority,setPriority]=useState('Routine');const [doctor,setDoctor]=useState(patient.doctor||doctors[0].name);const [err,setErr]=useState('');function submit(e:FormEvent){e.preventDefault();if(!bp.trim()||!temp.trim()||!weight.trim()){setErr('Complete blood pressure, temperature and weight.');return;}assignDoctor(patient.id,doctor,{bp,temp,weight,priority});onSaved();}return <Modal title="Triage assessment" onClose={onClose}><div className="mb-4 rounded-xl bg-[#eff2ef] p-3"><div className="text-sm font-semibold">{patient.name} <span className="ml-1 text-[10px] font-normal text-[#848e88]">{patient.id}</span></div><p className="mt-1 text-xs text-[#78827c]">{patient.symptoms}</p></div><form onSubmit={submit} className="space-y-4"><div className="grid grid-cols-3 gap-2">{[{label:'Blood pressure',value:bp,set:setBp,unit:'mmHg',placeholder:'120/80'},{label:'Temperature',value:temp,set:setTemp,unit:'°C',placeholder:'36.8'},{label:'Weight',value:weight,set:setWeight,unit:'kg',placeholder:'62'}].map(f=><label key={f.label} className="text-[10px] font-semibold">{f.label}<div className="relative mt-1"><input className="field pr-9 text-xs" value={f.value} onChange={e=>f.set(e.target.value)} placeholder={f.placeholder} data-testid={`input-vitals-${f.label.toLowerCase().replace(' ','-')}`}/><span className="absolute right-2 top-3 text-[9px] text-[#89938d]">{f.unit}</span></div></label>)}</div><label className="block text-xs font-semibold">Priority<select className="field mt-1.5" value={priority} onChange={e=>setPriority(e.target.value)} data-testid="select-triage-priority"><option>Routine</option><option>Urgent</option><option>Emergency</option></select></label><label className="block text-xs font-semibold">Assign to doctor<select className="field mt-1.5" value={doctor} onChange={e=>setDoctor(e.target.value)} data-testid="select-assign-doctor">{doctors.map(d=><option key={d.name} value={d.name}>{d.name} · {d.specialty}</option>)}</select></label>{err&&<p className="text-xs text-[#a84942]" role="alert">{err}</p>}<div className="flex gap-2 pt-1"><button type="button" onClick={onClose} className="btn-soft flex-1 py-3 text-xs" data-testid="button-cancel-assessment">Cancel</button><button className="btn-primary flex-1 py-3 text-xs" data-testid="button-complete-triage">Complete triage</button></div></form></Modal>}
function Modal({title,children,onClose}:{title:string;children:ReactNode;onClose:()=>void}){return <div className="fixed inset-0 z-50 flex items-center justify-center bg-[#202722]/35 p-4 backdrop-blur-[2px]" onMouseDown={e=>{if(e.target===e.currentTarget)onClose()}}><section className="w-full max-w-[480px] rounded-[22px] border border-white bg-[#f8f9f8] p-5 shadow-2xl md:p-6"><div className="mb-4 flex items-center justify-between"><h2 className="font-[family-name:var(--font-serif)] text-lg font-bold">{title}</h2><button onClick={onClose} className="grid h-8 w-8 place-items-center rounded-full bg-[#ecefec] text-[#68736c]" aria-label="Close dialog" data-testid="button-close-dialog"><X size={16}/></button></div>{children}</section></div>}
function DoctorPage(){const {user,patients,toast}=useApp();const [selected,setSelected]=useState<Patient|null>(null);const assigned=user?.doctor||user?.name||doctors[0].name;const queue=patients.filter(p=>p.state==='with_doctor'&&p.doctor===assigned);return <StaffLayout title="Doctor desk"><PageIntro eyebrow="Clinical workspace" title="Your patient list" sub={`Patients assigned to ${assigned}. Review triage notes and coordinate next steps.`}/><section className="sage-panel mb-5 flex flex-wrap items-center justify-between gap-4 p-5"><div className="flex items-center gap-3"><div className="grid h-11 w-11 place-items-center rounded-2xl bg-white/55 text-[#536a59]"><Stethoscope size={20}/></div><div><div className="text-[10px] uppercase tracking-[.12em] text-[#647569]">Signed in as</div><div className="text-sm font-bold">{assigned}</div></div></div><div className="text-right"><div className="font-[family-name:var(--font-serif)] text-2xl font-bold">{queue.length}</div><div className="text-[10px] text-[#647569]">patients to see</div></div></section><section className="panel overflow-hidden"><div className="border-b border-[#e8ebe8] px-5 py-4"><h3 className="text-sm font-semibold">Ready for consultation</h3><p className="mt-1 text-[11px] text-[#89938d]">Triage-complete patients assigned to you</p></div>{queue.length?<div className="divide-y divide-[#eceeec]">{queue.map(p=><div key={p.id} className="flex flex-wrap items-center gap-4 px-5 py-4" data-testid={`row-doctor-${p.id}`}><div className="grid h-10 w-10 place-items-center rounded-full bg-[#e5ebe6] text-sm font-bold text-[#526458]">{p.name.slice(0,1)}</div><div className="min-w-[140px] flex-1"><div className="text-sm font-semibold">{p.name}<span className="ml-2 text-[10px] font-normal text-[#919a95]">{p.id}</span></div><div className="mt-1 truncate text-xs text-[#818b85]">{p.symptoms}</div></div><div className="hidden text-right text-[10px] text-[#7b867f] sm:block">BP {p.vitals?.bp||'—'}<br/>Temp {p.vitals?.temp||'—'} °C</div><button onClick={()=>setSelected(p)} className="btn-primary flex items-center gap-2 px-4 py-2.5 text-xs" data-testid={`button-view-patient-${p.id}`}>Open record <ArrowRight size={14}/></button></div>)}</div>:<EmptyState title="No patients assigned" copy="When triage assigns a patient to you, their clinical summary will appear here." icon={Stethoscope}/>}</section>{selected&&<PatientDetail patient={selected} onClose={()=>setSelected(null)} onReferral={()=>{setSelected(null);setTimeout(()=>document.dispatchEvent(new CustomEvent('open-referral',{detail:selected})),10)}} toast={toast}/>}</StaffLayout>}
function PatientDetail({patient,onClose,onReferral,toast}:{patient:Patient;onClose:()=>void;onReferral:()=>void;toast:(s:string)=>void}){return <Modal title="Patient record" onClose={onClose}><div className="mb-4 flex items-center justify-between rounded-xl bg-[#eff2ef] p-3"><div><div className="text-sm font-semibold">{patient.name}</div><div className="mt-1 text-[10px] text-[#818b85]">{patient.id} · {patient.visitType}</div></div><StatusPill state={patient.state}/></div><div className="space-y-3"><div><div className="text-[10px] font-bold uppercase tracking-wider text-[#929a95]">Presenting concern</div><p className="mt-1 text-sm">{patient.symptoms}</p></div><div><div className="text-[10px] font-bold uppercase tracking-wider text-[#929a95]">Triage observations</div><div className="mt-2 grid grid-cols-3 gap-2">{[['Blood pressure',patient.vitals?.bp||'—'],['Temperature',patient.vitals?.temp?`${patient.vitals.temp} °C`:'—'],['Weight',patient.vitals?.weight?`${patient.vitals.weight} kg`:'—'],['Priority',patient.vitals?.priority||'Routine']].map(([a,b])=><div key={a} className="rounded-xl bg-[#eff2ef] p-3"><div className="text-[9px] text-[#89938d]">{a}</div><div className="mt-1 text-xs font-semibold">{b}</div></div>)}</div></div></div><div className="mt-5 flex gap-2"><button onClick={()=>toast('Visit note saved locally')} className="btn-soft flex-1 py-3 text-xs" data-testid="button-save-note">Save visit note</button><button onClick={onReferral} className="btn-primary flex-1 py-3 text-xs" data-testid="button-send-referral">Send referral <ArrowUpRight size={14} className="ml-1 inline"/></button></div></Modal>}
function ReferralEventHost(){const {toast}=useApp();const [patient,setPatient]=useState<Patient|null>(null);useEffect(()=>{const handle=(e:Event)=>setPatient((e as CustomEvent<Patient>).detail);document.addEventListener('open-referral',handle);return()=>document.removeEventListener('open-referral',handle)},[]);return patient?<ReferralModal patient={patient} onClose={()=>setPatient(null)} onSent={()=>{toast('Referral added to inbox');setPatient(null)}}/>:null}
function ReferralsPage(){const {referrals,toast}=useApp();const [referral,setReferral]=useState<Patient|null>(null);useEffect(()=>{const handle=(e:Event)=>setReferral((e as CustomEvent<Patient>).detail);document.addEventListener('open-referral',handle);return()=>document.removeEventListener('open-referral',handle)},[]);return <StaffLayout title="Referrals"><PageIntro eyebrow="Shared care" title="Referral inbox" sub="A clear view of patients referred to another service."/><div className="grid gap-3 sm:grid-cols-3"><MiniStat label="All referrals" value={referrals.length} icon={ClipboardPlus}/><MiniStat label="Radiology" value={referrals.filter(r=>r.department==='Radiology').length} icon={Activity}/><MiniStat label="Laboratory" value={referrals.filter(r=>r.department==='Lab').length} icon={FileHeart}/></div><section className="panel mt-5 overflow-hidden"><div className="border-b border-[#e8ebe8] px-5 py-4"><h3 className="text-sm font-semibold">Recent referrals</h3><p className="mt-1 text-[11px] text-[#89938d]">Created by doctors across outpatient care</p></div>{referrals.length?<div className="divide-y divide-[#eceeec]">{referrals.map(r=><div className="flex flex-wrap items-center gap-4 px-5 py-4" key={r.id} data-testid={`row-referral-${r.id}`}><div className="grid h-10 w-10 place-items-center rounded-xl bg-[#e6ebe7] text-[#63766a]"><ClipboardPlus size={18}/></div><div className="min-w-[150px] flex-1"><div className="text-sm font-semibold">{r.patientName}<span className="ml-2 text-[10px] font-normal text-[#919a95]">{r.patientId}</span></div><div className="mt-1 text-xs text-[#818b85]">{r.reason}</div></div><div className="min-w-[100px] text-xs font-semibold">{r.department}<div className="mt-1 text-[10px] font-normal text-[#89938d]">Referred by {r.doctor}</div></div><span className={`rounded-full px-2.5 py-1 text-[10px] font-semibold ${r.urgency==='Urgent'?'bg-[#f5e5df] text-[#9a5144]':r.urgency==='Priority'?'bg-[#f5ecd9] text-[#886b38]':'bg-[#e6ece7] text-[#63756a]'}`}>{r.urgency}</span></div>)}</div>:<EmptyState title="No referrals yet" copy="Referrals created during a consultation will appear here." icon={ClipboardPlus}/>}</section>{referral&&<ReferralModal patient={referral} onClose={()=>setReferral(null)} onSent={()=>{toast('Referral added to inbox');setReferral(null)}}/>}</StaffLayout>}
function ReferralModal({patient,onClose,onSent}:{patient:Patient;onClose:()=>void;onSent:()=>void}){const {sendReferral}=useApp();const [department,setDepartment]=useState('Radiology');const [reason,setReason]=useState('');const [urgency,setUrgency]=useState('Routine');const [err,setErr]=useState('');function submit(e:FormEvent){e.preventDefault();if(reason.trim().length<6){setErr('Add a brief reason for the referral.');return;}sendReferral(patient.id,department,reason.trim(),urgency);onSent();}return <Modal title={`Refer ${patient.name}`} onClose={onClose}><p className="mb-4 text-xs text-[#758079]">Send a referral from {patient.doctor||'your clinic'} for care coordination.</p><form onSubmit={submit} className="space-y-4"><label className="block text-xs font-semibold">Destination department<select className="field mt-1.5" value={department} onChange={e=>setDepartment(e.target.value)} data-testid="select-referral-department"><option>Radiology</option><option>Lab</option></select></label><label className="block text-xs font-semibold">Reason for referral<textarea className="field mt-1.5 min-h-24" value={reason} onChange={e=>{setReason(e.target.value);setErr('')}} placeholder="What investigation or support is needed?" data-testid="input-referral-reason"/></label><label className="block text-xs font-semibold">Urgency<select className="field mt-1.5" value={urgency} onChange={e=>setUrgency(e.target.value)} data-testid="select-referral-urgency"><option>Routine</option><option>Priority</option><option>Urgent</option></select></label>{err&&<p className="text-xs text-[#a84942]" role="alert">{err}</p>}<div className="flex gap-2"><button type="button" onClick={onClose} className="btn-soft flex-1 py-3 text-xs" data-testid="button-cancel-referral">Cancel</button><button className="btn-primary flex-1 py-3 text-xs" data-testid="button-submit-referral">Send referral <ArrowRight size={14} className="ml-1 inline"/></button></div></form></Modal>}

function AdminPage(){const {patients,referrals}=useApp();const [query,setQuery]=useState('');const [filter,setFilter]=useState('All');const filtered=patients.filter(p=>(filter==='All'||p.state===filter)&&`${p.name} ${p.id} ${p.symptoms}`.toLowerCase().includes(query.toLowerCase()));return <StaffLayout title="Overview"><PageIntro eyebrow="Hospital operations" title="Today at a glance" sub="An overview of patient flow across outpatient services."/><div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4"><MiniStat label="Patients today" value={patients.length} icon={Users}/><MiniStat label="In triage" value={patients.filter(p=>p.state==='waiting_for_triage').length} icon={Clock3}/><MiniStat label="With doctors" value={patients.filter(p=>p.state==='with_doctor').length} icon={Stethoscope}/><MiniStat label="Referrals sent" value={referrals.length} icon={ClipboardPlus}/></div><section className="panel mt-5 overflow-hidden"><div className="flex flex-wrap items-center justify-between gap-4 border-b border-[#e8ebe8] px-5 py-4"><div><h3 className="text-sm font-semibold">All patients</h3><p className="mt-1 text-[11px] text-[#89938d]">Current location and care status</p></div><div className="flex flex-wrap gap-2"><div className="relative"><SearchIcon/><input className="field h-9 w-[180px] pl-9 text-xs" value={query} onChange={e=>setQuery(e.target.value)} placeholder="Search patients" data-testid="input-search-patients"/></div><select className="field h-9 w-auto py-1.5 text-xs" value={filter} onChange={e=>setFilter(e.target.value)} data-testid="select-patient-filter"><option value="All">All states</option><option value="waiting_for_triage">Waiting for triage</option><option value="with_doctor">With doctor</option><option value="referred">Referred</option><option value="pharmacy">Pharmacy</option><option value="complete">Complete</option></select></div></div>{filtered.length?<div className="overflow-x-auto"><table className="w-full min-w-[700px] text-left"><thead className="bg-[#f0f2f0] text-[10px] uppercase tracking-wider text-[#89938d]"><tr><th className="px-5 py-3 font-semibold">Patient</th><th className="px-4 py-3 font-semibold">Visit</th><th className="px-4 py-3 font-semibold">Concern</th><th className="px-4 py-3 font-semibold">Assigned doctor</th><th className="px-5 py-3 font-semibold">Current status</th></tr></thead><tbody className="divide-y divide-[#eceeec]">{filtered.map(p=><tr key={p.id} data-testid={`row-admin-${p.id}`} className="hover:bg-[#f7f8f7]"><td className="px-5 py-3.5"><div className="text-xs font-semibold">{p.name}</div><div className="mt-1 text-[10px] text-[#89938d]">{p.id}</div></td><td className="px-4 py-3.5 text-xs text-[#6f7a73]">{p.visitType}</td><td className="max-w-[230px] truncate px-4 py-3.5 text-xs text-[#6f7a73]">{p.symptoms}</td><td className="px-4 py-3.5 text-xs text-[#6f7a73]">{p.doctor||'—'}</td><td className="px-5 py-3.5"><StatusPill state={p.state}/></td></tr>)}</tbody></table></div>:<EmptyState title="No matching patients" copy="Try a different name, ID or status filter." icon={Users}/>}</section><div className="mt-5 grid gap-4 md:grid-cols-[1.1fr_.9fr]"><section className="sage-panel flex items-start justify-between gap-4 p-5"><div><div className="mb-1 text-[10px] font-bold uppercase tracking-[.14em] text-[#5d7162]">Referral coordination</div><h3 className="text-base font-bold">Keep services connected</h3><p className="mt-1 max-w-sm text-xs leading-relaxed text-[#627166]">{referrals.length?`${referrals.length} referral${referrals.length===1?'':'s'} in the inbox, ready for follow-up.`:'New referrals from doctors will appear in the shared inbox.'}</p><Link href="/staff/referrals" className="mt-4 inline-flex items-center gap-2 rounded-xl bg-[#29312c] px-4 py-2.5 text-xs font-semibold text-white no-underline" data-testid="link-admin-referrals">Open referral inbox <ArrowRight size={14}/></Link></div><ClipboardPlus className="shrink-0 text-[#627765]" size={23}/></section><section className="panel p-5"><div className="flex items-center justify-between"><h3 className="text-sm font-semibold">Flow snapshot</h3><span className="text-[10px] text-[#89938d]">Today</span></div><div className="mt-4 space-y-3">{[{label:'Triage',n:patients.filter(p=>p.state==='waiting_for_triage').length,color:'#b6c9b9'},{label:'Consultation',n:patients.filter(p=>p.state==='with_doctor').length,color:'#8da995'},{label:'Referred',n:patients.filter(p=>p.state==='referred').length,color:'#c8d4cb'}].map(item=><div key={item.label} className="flex items-center gap-3"><span className="w-20 text-xs text-[#758079]">{item.label}</span><div className="h-2 flex-1 overflow-hidden rounded-full bg-[#edf0ed]"><div className="h-full rounded-full" style={{width:`${patients.length?Math.max(5,item.n/patients.length*100):0}%`,backgroundColor:item.color}}/></div><span className="w-4 text-right text-xs font-semibold">{item.n}</span></div>)}</div></section></div></StaffLayout>}
function SearchIcon(){return <span className="pointer-events-none absolute left-3 top-[11px] text-[#89938d]"><Search size={15}/></span>}
function NotFound(){return <div className="app-shell grid min-h-[70dvh] place-items-center p-6"><section className="panel max-w-md p-8 text-center"><div className="mx-auto mb-4 grid h-12 w-12 place-items-center rounded-2xl bg-[#e7ece8] text-[#627568]"><Hospital size={22}/></div><h1 className="font-[family-name:var(--font-serif)] text-2xl font-bold">This page isn’t here</h1><p className="mt-2 text-sm text-[#7b857f]">The address may have changed. Start again from the welcome page.</p><Link className="btn-primary mt-5 inline-flex items-center gap-2 px-5 py-3 text-sm no-underline" href="/" data-testid="link-not-found-home">Go to welcome <ArrowRight size={15}/></Link></section></div>}
function RouteGuard({children,role}:{children:ReactNode;role?:Role}){const {user}=useApp();const [,setPath]=useLocation();useEffect(()=>{if(!user)setPath(role==='patient'?'/auth/patient':'/auth/staff');else if(role&&user.role!==role&&!(user.role==='admin'&&role!=='patient'))setPath(user.role==='patient'?'/patient/home':user.role==='triage'?'/staff/triage':user.role==='doctor'?'/staff/doctor':'/staff/admin')},[user,role,setPath]);if(!user||role&&user.role!==role&&!(user.role==='admin'&&role!=='patient'))return <div className="app-shell grid min-h-[60dvh] place-items-center text-sm text-[#738078]">Opening your workspace…</div>;return <>{children}</>}
function App(){return <AppProvider><Switch><Route path="/" component={Landing}/><Route path="/auth/patient" component={PatientAuth}/><Route path="/auth/staff" component={StaffAuth}/><Route path="/patient/home"><RouteGuard role="patient"><PatientHome/></RouteGuard></Route><Route path="/patient/book"><RouteGuard role="patient"><PatientBook/></RouteGuard></Route><Route path="/patient/checkin"><RouteGuard role="patient"><CheckIn/></RouteGuard></Route><Route path="/patient/tracker"><RouteGuard role="patient"><Tracker/></RouteGuard></Route><Route path="/patient/records"><RouteGuard role="patient"><PatientRecords/></RouteGuard></Route><Route path="/patient/profile"><RouteGuard role="patient"><PatientProfile/></RouteGuard></Route><Route path="/staff/triage"><RouteGuard role="triage"><TriagePage/></RouteGuard></Route><Route path="/staff/doctor"><RouteGuard role="doctor"><DoctorPage/></RouteGuard></Route><Route path="/staff/admin"><RouteGuard role="admin"><AdminPage/></RouteGuard></Route><Route path="/staff/referrals"><RouteGuard role="triage"><ReferralsPage/></RouteGuard></Route><Route component={NotFound}/></Switch><ResetControl/></AppProvider>}
export default App;
